//! Desktop-only presentation of pending first-party OAuth requests.
use serde::Serialize;use std::{collections::HashMap,sync::Mutex};
#[derive(Clone,Serialize)]#[serde(rename_all="camelCase")]pub(crate)struct Pending{pub request_id:String,pub client_name:String,pub redirect_uri:String,pub resource:String,pub expires_at:u64}
static PENDING:Mutex<Option<HashMap<String,Pending>>>=Mutex::new(None);
fn now()->u64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs()}
pub(crate)fn observed(request_id:&str,client_name:&str,redirect_uri:&str,resource:&str,expires:u64){if request_id.len()!=64||client_name.len()>120||redirect_uri.len()>4096||resource.len()>2048{return;}if let Ok(mut slot)=PENDING.lock(){let rows=slot.get_or_insert_with(HashMap::new);rows.retain(|_,row|row.expires_at>now()*1000);if rows.len()<128{rows.insert(request_id.into(),Pending{request_id:request_id.into(),client_name:client_name.into(),redirect_uri:redirect_uri.into(),resource:resource.into(),expires_at:expires*1000});}}}
pub(crate)fn consumed(id:&str){if let Ok(mut slot)=PENDING.lock(){if let Some(rows)=slot.as_mut(){rows.remove(id);}}}
fn local_callback(value:&str)->bool{url::Url::parse(value).ok().is_some_and(|url|url.scheme()=="http"&&url.username().is_empty()&&url.password().is_none()&&url.host_str().is_some_and(|host|host=="localhost"||host.trim_matches(['[',']']).parse::<std::net::IpAddr>().is_ok_and(|ip|ip.is_loopback())))}
pub(crate)fn list(endpoint:&str)->Vec<Pending>{PENDING.lock().ok().and_then(|slot|slot.as_ref().map(|rows|rows.values().filter(|row|row.resource==endpoint&&local_callback(&row.redirect_uri)&&row.expires_at>(now()+5)*1000).cloned().collect())).unwrap_or_default()}
fn link(endpoint:&str,row:&Pending,code:&str)->Result<String,String>{let mut url=url::Url::parse(endpoint).map_err(|_|"CLAUDE_AUTH_REQUEST_INVALID")?;if url.scheme()!="https"||url.path()!="/mcp"||!url.username().is_empty()||url.password().is_some()||url.query().is_some()||url.fragment().is_some()||row.resource!=endpoint||!local_callback(&row.redirect_uri)||row.request_id.len()!=64||!row.request_id.bytes().all(|c|c.is_ascii_hexdigit())||code.len()!=6||!code.bytes().all(|c|c.is_ascii_digit()){return Err("CLAUDE_AUTH_REQUEST_INVALID".into());}url.set_path("/assistant/connect");url.query_pairs_mut().append_pair("request",&row.request_id);url.set_fragment(Some(&format!("agbrio-pair-code={code}")));Ok(url.into())}
pub(crate)fn open(host:&crate::HostRuntime,id:&str)->Result<(),String>{if !cfg!(windows){return Err("PLATFORM_NOT_YET_SUPPORTED".into());}let endpoint=crate::assistant_connection_endpoint::endpoint(host.mobile_configuration().map(|c|c.allowed_origin).as_deref(),None).ok_or("CLAUDE_MCP_ENDPOINT_NOT_READY")?;let row=list(&endpoint).into_iter().find(|row|row.request_id==id).ok_or("CLAUDE_AUTH_REQUEST_EXPIRED")?;let code=crate::web_auth::global()?.issue()?;let target=link(&endpoint,&row,&code.code)?;
 #[cfg(windows)]{use std::os::windows::process::CommandExt;std::process::Command::new(std::path::PathBuf::from(std::env::var_os("SystemRoot").ok_or("CLAUDE_AUTH_PAGE_OPEN_UNCONFIRMED")?).join("System32/rundll32.exe")).arg("url.dll,FileProtocolHandler").arg(target).creation_flags(0x08000000).spawn().map_err(|_|"CLAUDE_AUTH_PAGE_OPEN_UNCONFIRMED")?;}
 Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn code_is_only_in_fragment_and_exact_request_and_resource_are_bound(){let row=Pending{request_id:"a".repeat(64),client_name:"fixture".into(),redirect_uri:"http://127.0.0.1/callback".into(),resource:"https://owner.invalid/mcp".into(),expires_at:u64::MAX};let u=url::Url::parse(&link(&row.resource,&row,"654321").unwrap()).unwrap();assert!(!u.query().unwrap().contains("654321"));assert_eq!(u.fragment(),Some("agbrio-pair-code=654321"));assert!(link("https://other.invalid/mcp",&row,"654321").is_err());assert!(link(&row.resource,&row,"not-a-code").is_err());let remote=Pending{redirect_uri:"https://remote.invalid/callback".into(),..row.clone()};assert!(link(&remote.resource,&remote,"654321").is_err());}}
